-- Failed validation is a normal RPC result so its request record commits.
-- Raw requested_period deliberately has no FK: even an invalid period must count as a request.
create table if not exists public.api_request_attempts(
  id bigint generated always as identity primary key,
  attempt_type text not null check(attempt_type in('vote','submission')),
  cookie_hash text not null, client_ip text, requested_period text,
  created_at timestamptz not null default clock_timestamp()
);
alter table public.api_request_attempts enable row level security;
revoke all on public.api_request_attempts from public,anon,authenticated;
create index if not exists api_attempt_cookie_time on public.api_request_attempts(attempt_type,cookie_hash,created_at desc);
create index if not exists api_attempt_ip_time on public.api_request_attempts(attempt_type,client_ip,created_at desc);
create index if not exists api_attempt_expiry on public.api_request_attempts(created_at);
create or replace function public.consume_api_attempt(p_type text,p_period text,p_cookie text)
returns void language plpgsql security definer set search_path=public as $rate$
declare cfg public.security_settings%rowtype; cookie_key text=md5(coalesce(left(btrim(p_cookie),128),'')); ip text; lock_key bigint; cookie_limit int; ip_limit int;
begin
  select * into strict cfg from public.security_settings where id=true;
  ip=public.request_client_ip();
  -- All RPCs use rate keys (sorted) -> actor/period -> period -> song -> report.
  for lock_key in select distinct key from unnest(array[
    hashtextextended('rate-cookie:'||p_type||':'||cookie_key,0),
    case when ip is null then null else hashtextextended('rate-ip:'||p_type||':'||ip,0) end
  ]) key where key is not null order by key loop perform pg_advisory_xact_lock(lock_key); end loop;
  if p_type='vote' then cookie_limit=cfg.vote_cookie_per_minute; ip_limit=cfg.vote_ip_per_minute;
  elsif p_type='submission' then cookie_limit=cfg.submission_cookie_per_minute; ip_limit=cfg.submission_ip_per_minute;
  else raise exception 'Invalid request type.'; end if;
  if (select count(*) from public.api_request_attempts where attempt_type=p_type and cookie_hash=cookie_key and created_at>=clock_timestamp()-interval '1 minute')>=cookie_limit
    or (ip is not null and (select count(*) from public.api_request_attempts where attempt_type=p_type and client_ip=ip and created_at>=clock_timestamp()-interval '1 minute')>=ip_limit) then
    raise exception '请求过于频繁，请稍后再试。' using errcode='P0001';
  end if;
  insert into public.api_request_attempts(attempt_type,cookie_hash,client_ip,requested_period) values(p_type,cookie_key,ip,left(p_period,64));
end;
$rate$;
revoke all on function public.consume_api_attempt(text,text,text) from public,anon,authenticated;
create or replace function public.purge_expired_request_attempts()
returns bigint language plpgsql security definer set search_path=public as $purge$
declare removed bigint;
begin
  delete from public.api_request_attempts where created_at<clock_timestamp()-interval '7 days'; get diagnostics removed=row_count;
  delete from public.vote_attempts where created_at<clock_timestamp()-interval '7 days';
  return removed;
end;
$purge$;
revoke all on function public.purge_expired_request_attempts() from public,anon,authenticated;

-- Request and vote RPCs are replaced below. Existing public argument names remain compatible.
create or replace function public.apply_song_vote(p_song_id uuid,p_period text,p_cookie text,p_action text,p_reason text)
returns table(liked boolean,disliked boolean,likes_count integer,dislikes_count integer)
language plpgsql security definer set search_path=public as $vote$
declare identity text; target uuid; period_record public.playlist_periods%rowtype; song_record public.songs%rowtype; maximum int; already boolean;
begin
  identity=public.assert_valid_voter_cookie(p_cookie);
  begin target=p_period::uuid; exception when invalid_text_representation then raise exception '征集期无效，请刷新页面。'; end;
  if target is null then raise exception '征集期无效，请刷新页面。'; end if;
  if p_action is null or p_action not in('like','unlike','dislike','undislike') then raise exception 'Unknown voting action.'; end if;
  if p_action='dislike' and length(trim(coalesce(p_reason,''))) not between 1 and 20 then raise exception '点踩理由须为 1–20 字。'; end if;
  perform pg_advisory_xact_lock(hashtextextended('actor:'||target::text||':'||identity,0));
  select * into period_record from public.playlist_periods where id=target for share;
  if not found or period_record.status<>'active' or clock_timestamp() not between period_record.starts_at and period_record.ends_at then
    raise exception '征集已结束或尚未开始，请刷新页面。';
  end if;
  select * into song_record from public.songs where id=p_song_id and period_id=target for update;
  if not found or song_record.is_locked then raise exception '歌曲已锁定或不存在，请刷新页面。'; end if;
  if p_action='like' then
    select exists(select 1 from public.song_likes l where l.song_id=p_song_id and l.voter_cookie=identity) into already;
    if not already then
      select max_likes_per_period into maximum from public.security_settings where id=true;
      if (select count(*) from public.song_likes l where l.period_id=target and l.voter_cookie=identity)>=maximum then
        raise exception '本浏览器已达到本期喜欢数量上限。';
      end if;
      delete from public.song_dislikes d where d.song_id=p_song_id and d.voter_cookie=identity;
      insert into public.song_likes(song_id,user_id,voter_cookie,voter_ip,playlist_date,period_id)
        values(p_song_id,identity,identity,public.request_client_ip(),target::text,target);
    end if;
  elsif p_action='unlike' then
    delete from public.song_likes l where l.song_id=p_song_id and l.voter_cookie=identity;
  elsif p_action='dislike' then
    select exists(select 1 from public.song_dislikes d where d.song_id=p_song_id and d.voter_cookie=identity) into already;
    if not already then
      delete from public.song_likes l where l.song_id=p_song_id and l.voter_cookie=identity;
      insert into public.song_dislikes(song_id,user_id,voter_cookie,voter_ip,playlist_date,period_id)
        values(p_song_id,identity,identity,public.request_client_ip(),target::text,target);
      insert into public.song_reports(song_id,playlist_date,period_id,reporter_cookie,reporter_ip,reason)
        values(p_song_id,target::text,target,identity,public.request_client_ip(),trim(p_reason))
        on conflict(song_id,reporter_cookie) where status='pending' do update set reason=excluded.reason;
    end if;
  else
    delete from public.song_dislikes d where d.song_id=p_song_id and d.voter_cookie=identity;
  end if;
  -- The song row was locked before reading/modifying either vote table.
  update public.songs s set likes_count=(select count(*)::int from public.song_likes l where l.song_id=p_song_id),
    dislikes_count=(select count(*)::int from public.song_dislikes d where d.song_id=p_song_id) where s.id=p_song_id;
  return query select exists(select 1 from public.song_likes l where l.song_id=p_song_id and l.voter_cookie=identity),
    exists(select 1 from public.song_dislikes d where d.song_id=p_song_id and d.voter_cookie=identity),s.likes_count,s.dislikes_count
    from public.songs s where s.id=p_song_id;
end;
$vote$;
revoke all on function public.apply_song_vote(uuid,text,text,text,text) from public,anon,authenticated;
drop function if exists public.toggle_song_like(uuid,text,text,text);
create function public.toggle_song_like(p_song_id uuid,p_playlist_date text,p_voter_cookie text,p_action text)
returns table(liked boolean,likes_count integer,error_code text,error_message text)
language plpgsql security definer set search_path=public as $like$
begin
  perform public.consume_api_attempt('vote',p_playlist_date,p_voter_cookie);
  begin
    if p_action is null or p_action not in('like','unlike') then raise exception 'Unknown voting action.'; end if;
    return query select r.liked,r.likes_count,null::text,null::text from public.apply_song_vote(p_song_id,p_playlist_date,p_voter_cookie,p_action,null) r;
  exception when others then
    -- Only this subtransaction is rolled back; consume_api_attempt remains committed.
    return query select false,0,sqlstate,case when sqlstate in('P0001','23505','23503','23514','22P02') then sqlerrm else '操作失败，请稍后重试。' end;
  end;
end;
$like$;
drop function if exists public.toggle_song_dislike(uuid,text,text,text);
drop function if exists public.toggle_song_dislike(uuid,text,text,text,text);
create function public.toggle_song_dislike(p_song_id uuid,p_playlist_date text,p_voter_cookie text,p_action text,p_reason text default null)
returns table(disliked boolean,dislikes_count integer,error_code text,error_message text)
language plpgsql security definer set search_path=public as $dislike$
begin
  perform public.consume_api_attempt('vote',p_playlist_date,p_voter_cookie);
  begin
    if p_action is null or p_action not in('dislike','undislike') then raise exception 'Unknown voting action.'; end if;
    return query select r.disliked,r.dislikes_count,null::text,null::text from public.apply_song_vote(p_song_id,p_playlist_date,p_voter_cookie,p_action,p_reason) r;
  exception when others then
    return query select false,0,sqlstate,case when sqlstate in('P0001','23505','23503','23514','22P02') then sqlerrm else '操作失败，请稍后重试。' end;
  end;
end;
$dislike$;

drop function if exists public.submit_song(text,text,text,text);
create function public.submit_song(p_title text,p_artist text,p_playlist_date text,p_voter_cookie text)
returns table(id uuid,title text,artist text,playlist_date text,likes_count integer,created_at timestamptz,error_code text,error_message text)
language plpgsql security definer set search_path=public as $submit$
declare identity text; target uuid; period_record public.playlist_periods%rowtype; maximum int;
begin
  perform public.consume_api_attempt('submission',p_playlist_date,p_voter_cookie);
  begin
    identity=public.assert_valid_voter_cookie(p_voter_cookie);
    if length(trim(coalesce(p_title,''))) not between 1 and 80 or length(trim(coalesce(p_artist,''))) not between 1 and 80 then
      raise exception '歌名和歌手须为 1–80 字。';
    end if;
    begin target=p_playlist_date::uuid; exception when invalid_text_representation then raise exception '征集期无效，请刷新页面。'; end;
    if target is null then raise exception '征集期无效，请刷新页面。'; end if;
    perform pg_advisory_xact_lock(hashtextextended('actor:'||target::text||':'||identity,0));
    select * into period_record from public.playlist_periods where public.playlist_periods.id=target for share;
    if not found or period_record.status<>'active' or clock_timestamp() not between period_record.starts_at and period_record.ends_at then
      raise exception '征集已结束或尚未开始，请刷新页面。';
    end if;
    select submission_cookie_per_period into maximum from public.security_settings where public.security_settings.id=true;
    if (select count(*) from public.songs s where s.period_id=target and s.created_by='cookie:'||md5(identity))>=maximum then
      raise exception '本浏览器已达到本期投稿数量上限。';
    end if;
    return query insert into public.songs as s(title,artist,title_lower,artist_lower,playlist_date,period_id,created_by)
      values(trim(p_title),trim(p_artist),lower(trim(p_title)),lower(trim(p_artist)),target::text,target,'cookie:'||md5(identity))
      returning s.id,s.title,s.artist,s.playlist_date,s.likes_count,s.created_at,null::text,null::text;
  exception when unique_violation then
    return query select null::uuid,null::text,null::text,null::text,0,null::timestamptz,'23505'::text,'本期已有同名、同歌手的歌曲。'::text;
  when others then
    return query select null::uuid,null::text,null::text,null::text,0,null::timestamptz,sqlstate,
      case when sqlstate in('P0001','23503','23514','22P02') then sqlerrm else '投稿失败，请稍后重试。' end;
  end;
end;
$submit$;
revoke all on function public.toggle_song_like(uuid,text,text,text) from public;
revoke all on function public.toggle_song_dislike(uuid,text,text,text,text) from public;
revoke all on function public.submit_song(text,text,text,text) from public;
grant execute on function public.toggle_song_like(uuid,text,text,text) to anon,authenticated;
grant execute on function public.toggle_song_dislike(uuid,text,text,text,text) to anon,authenticated;
grant execute on function public.submit_song(text,text,text,text) to anon,authenticated;

-- Internal moderation implementation follows the same song -> report lock order as voting.
create or replace function public.review_song_report(p_report_id uuid,p_approve boolean)
returns void language plpgsql security definer set search_path=public as $review$
declare report_record public.song_reports%rowtype; target uuid;
begin
  if public.is_current_user_admin() is not true then raise exception 'Admin permission required.'; end if;
  select song_id into target from public.song_reports where public.song_reports.id=p_report_id;
  if target is null then raise exception 'Pending report not found.'; end if;
  perform 1 from public.songs where public.songs.id=target for update;
  select * into report_record from public.song_reports where public.song_reports.id=p_report_id and status='pending' for update;
  if not found then raise exception 'Pending report not found.'; end if;
  update public.song_reports set status=case when p_approve then 'approved' else 'rejected' end,reviewed_by=auth.uid()::text,reviewed_at=clock_timestamp() where public.song_reports.id=p_report_id;
  if p_approve then update public.songs set is_locked=true,locked_at=clock_timestamp(),locked_by=auth.uid()::text where public.songs.id=target; end if;
end;
$review$;
revoke all on function public.review_song_report(uuid,boolean) from public,anon,authenticated;



-- Keep table-level mutual exclusion even for future trusted import scripts.
create or replace function public.guard_vote_sentiment()
returns trigger language plpgsql security definer set search_path=public as $guard$
declare opposite text; found_opposite boolean;
begin
  perform pg_advisory_xact_lock(hashtextextended('actor:'||new.period_id::text||':'||coalesce(new.voter_cookie,new.user_id),0));
  perform 1 from public.songs where id=new.song_id for update;
  opposite=case when tg_table_name='song_likes' then 'song_dislikes' else 'song_likes' end;
  execute format('select exists(select 1 from public.%I where song_id=$1 and coalesce(voter_cookie,user_id)=$2)',opposite)
    into found_opposite using new.song_id,coalesce(new.voter_cookie,new.user_id);
  if found_opposite then raise exception '同一访客不能同时喜欢和点踩同一首歌。'; end if;
  return new;
end;
$guard$;
revoke all on function public.guard_vote_sentiment() from public,anon,authenticated;
drop trigger if exists b_guard_sentiment on public.song_likes;
create trigger b_guard_sentiment before insert or update on public.song_likes for each row execute function public.guard_vote_sentiment();
drop trigger if exists b_guard_sentiment on public.song_dislikes;
create trigger b_guard_sentiment before insert or update on public.song_dislikes for each row execute function public.guard_vote_sentiment();

create or replace function public.admin_update_playlist_period(p_period_id uuid,p_title text,p_starts_at timestamptz,p_ends_at timestamptz)
returns void language plpgsql security definer set search_path=public as $edit$
declare previous public.playlist_periods%rowtype;
begin
  if public.is_current_user_admin() is not true then raise exception 'Admin permission required.'; end if;
  if p_title is null or length(trim(p_title)) not between 1 and 80 or p_starts_at is null or p_ends_at is null or p_ends_at<=p_starts_at then raise exception '请填写标题和有效的征集时间。'; end if;
  select * into previous from public.playlist_periods where id=p_period_id for update;
  if not found or previous.status<>'active' then raise exception '当前征集期已变化，请刷新后重试。'; end if;
  update public.playlist_periods set title=trim(p_title),starts_at=p_starts_at,ends_at=p_ends_at,updated_at=clock_timestamp() where id=p_period_id;
  insert into public.admin_action_log(actor_id,actor_name,action,target_id,details) values(auth.uid(),coalesce(auth.jwt()->>'email',auth.uid()::text),'edit_period',p_period_id,
    jsonb_build_object('before',to_jsonb(previous),'title',trim(p_title),'starts_at',p_starts_at,'ends_at',p_ends_at));
end;
$edit$;
create or replace function public.admin_archive_playlist_period(p_period_id uuid)
returns void language plpgsql security definer set search_path=public as $archive$
begin
  if public.is_current_user_admin() is not true then raise exception 'Admin permission required.'; end if;
  update public.playlist_periods set status='archived',archived_at=clock_timestamp(),updated_at=clock_timestamp() where id=p_period_id and status='active';
  if not found then raise exception '当前征集期已变化，请刷新后重试。'; end if;
  insert into public.admin_action_log(actor_id,actor_name,action,target_id) values(auth.uid(),coalesce(auth.jwt()->>'email',auth.uid()::text),'archive_period',p_period_id);
end;
$archive$;
revoke all on function public.admin_update_playlist_period(uuid,text,timestamptz,timestamptz) from public,anon,authenticated;
revoke all on function public.admin_archive_playlist_period(uuid) from public,anon,authenticated;
grant execute on function public.admin_update_playlist_period(uuid,text,timestamptz,timestamptz) to authenticated;
grant execute on function public.admin_archive_playlist_period(uuid) to authenticated;

create or replace function public.admin_save_broadcast_playlist(p_period_id uuid,p_items jsonb,p_version integer)
returns integer language plpgsql security definer set search_path=public as $board$
declare current_version int; next_version int; old_items jsonb; next_items jsonb='[]'::jsonb; item jsonb; old_item jsonb; canonical jsonb; song_record public.songs%rowtype;
begin
  if public.is_current_user_admin() is not true then raise exception 'Admin permission required.'; end if;
  if p_items is null or jsonb_typeof(p_items)<>'array' then raise exception '歌单格式无效。'; end if;
  if jsonb_array_length(p_items)>500 or p_version is null or p_version<0 then raise exception '歌单数量或版本无效。'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_period_id::text,0));
  perform 1 from public.playlist_periods where id=p_period_id for share;
  if not found then raise exception '征集期不存在。'; end if;
  select version,items into current_version,old_items from public.broadcast_playlists where period_id=p_period_id for update;
  if coalesce(current_version,0)<>p_version then raise exception '歌单已被其他管理员更新，请重新读取后再修改。'; end if;
  if exists(select 1 from jsonb_array_elements(p_items) i where jsonb_typeof(i)<>'object' or i->>'song_id' is null or i->>'status' is null or i->>'status' not in('candidate','confirmed')) then raise exception '歌单条目格式无效。'; end if;
  if jsonb_array_length(p_items)<>(select count(distinct i->>'song_id') from jsonb_array_elements(p_items) i) then raise exception '歌单不能包含重复歌曲。'; end if;
  -- Deterministic song lock order shared with all playlist writers.
  perform 1 from public.songs s where s.id::text in(select i->>'song_id' from jsonb_array_elements(p_items) i) order by s.id for share;
  for item in select value from jsonb_array_elements(p_items) loop
    select * into song_record from public.songs where id::text=item->>'song_id' and playlist_date=p_period_id::text;
    if not found or (item->>'status'='confirmed' and song_record.is_locked) then raise exception '歌单包含不存在、其他征集期或已锁定的确认歌曲，请重新读取并调整。'; end if;
    canonical=jsonb_build_object('song_id',song_record.id,'status',item->>'status');
    if item->>'status'='confirmed' then
      select value into old_item from jsonb_array_elements(coalesce(old_items,'[]'::jsonb)) where value->>'song_id'=item->>'song_id' and value->>'status'='confirmed';
      if old_item->'snapshot' is not null and jsonb_typeof(old_item->'snapshot')='object' then
        canonical=canonical||jsonb_build_object('snapshot',old_item->'snapshot');
      else
        canonical=canonical||jsonb_build_object('snapshot',jsonb_build_object('title',song_record.title,'artist',song_record.artist,'likes_count',song_record.likes_count,'captured_at',clock_timestamp(),'source','confirmation'));
      end if;
    end if;
    next_items=next_items||jsonb_build_array(canonical);
  end loop;
  next_version=coalesce(current_version,0)+1;
  insert into public.broadcast_playlists(period_id,items,version,updated_by_name) values(p_period_id,next_items,next_version,coalesce(auth.jwt()->>'email',auth.uid()::text))
    on conflict(period_id) do update set items=excluded.items,version=excluded.version,updated_by_name=excluded.updated_by_name,updated_at=clock_timestamp();
  insert into public.admin_action_log(actor_id,actor_name,action,target_id,details) values(auth.uid(),coalesce(auth.jwt()->>'email',auth.uid()::text),'save_broadcast_playlist',p_period_id,jsonb_build_object('version',next_version,'items',next_items));
  return next_version;
end;
$board$;
revoke all on function public.admin_save_broadcast_playlist(uuid,jsonb,integer) from public;
grant execute on function public.admin_save_broadcast_playlist(uuid,jsonb,integer) to authenticated;

-- Existing confirmed lists get a one-time upgrade-time snapshot, not an invented past confirmation.
do $snapshot_preflight$
declare bad uuid;
begin
  select b.period_id into bad from public.broadcast_playlists b where exists(
    select 1 from jsonb_array_elements(b.items) i left join public.songs s on s.id::text=i->>'song_id'
    where s.id is null or s.period_id<>b.period_id or i->>'status' is null or i->>'status' not in('candidate','confirmed')) limit 1;
  if bad is not null then raise exception '播出歌单 % 含失效或错期条目，请先人工核实。',bad; end if;
end;
$snapshot_preflight$;
insert into public.database_repair_archive(source_table,source_id,reason,row_data,row_hash)
  select 'broadcast_playlists',b.period_id::text,'snapshot_upgrade',to_jsonb(b),md5(to_jsonb(b)::text) from public.broadcast_playlists b
  where exists(select 1 from jsonb_array_elements(b.items) i where i->>'status'='confirmed' and (i->'snapshot' is null or i->'snapshot'='null'::jsonb))
  on conflict do nothing;
update public.broadcast_playlists b set items=(
  select jsonb_agg(case when i->>'status'='confirmed' and (i->'snapshot' is null or i->'snapshot'='null'::jsonb)
    then i||jsonb_build_object('snapshot',jsonb_build_object('title',s.title,'artist',s.artist,'likes_count',s.likes_count,'captured_at',clock_timestamp(),'source','migration'))
    else i end order by ord) from jsonb_array_elements(b.items) with ordinality a(i,ord) join public.songs s on s.id::text=i->>'song_id'),
  version=version+1,updated_at=clock_timestamp()
  where exists(select 1 from jsonb_array_elements(b.items) i where i->>'status'='confirmed' and (i->'snapshot' is null or i->'snapshot'='null'::jsonb));


notify pgrst,'reload schema';

-- ===== supabase-test-mode.sql =====
-- After supabase-schema.sql, supabase-admin-workflow.sql and supabase-database-integrity.sql.
-- Preserves all existing periods, songs and votes. Safe to run repeatedly.

do $prerequisites$
begin
  if to_regclass('public.admin_action_log') is null
    or to_regprocedure('public.consume_api_attempt(text,text,text)') is null
    or (select count(*) from information_schema.columns where table_schema='public'
      and table_name in ('songs','song_likes','song_dislikes','song_reports','vote_attempts')
      and column_name='period_id' and udt_name='uuid') <> 5 then
    raise exception '测试模式依赖的数据库升级尚未完成。保留数据：先执行 supabase-admin-workflow.sql、supabase-database-integrity.sql；舍弃旧业务数据：完整执行 supabase-reset-and-rebuild.sql。';
  end if;
end;
$prerequisites$;

alter table public.playlist_periods add column if not exists is_test boolean not null default false;
grant select (is_test) on public.playlist_periods to anon,authenticated;

create table if not exists public.test_accounts (
  user_id uuid primary key references auth.users(id) on delete cascade,
  enabled boolean not null default true,
  granted_by uuid not null,
  updated_at timestamptz not null default now()
);
alter table public.test_accounts enable row level security;
revoke all on public.test_accounts from public, anon, authenticated;
grant select on public.test_accounts to authenticated;
drop policy if exists test_accounts_admin_read on public.test_accounts;
create policy test_accounts_admin_read on public.test_accounts for select to authenticated using (public.is_current_user_admin());

create or replace function public.is_current_user_tester()
returns boolean language sql stable security definer set search_path=public as $$
  select auth.uid() is not null and exists(select 1 from public.test_accounts where user_id=auth.uid() and enabled);
$$;
revoke all on function public.is_current_user_tester() from public;
grant execute on function public.is_current_user_tester() to anon, authenticated;

create or replace function public.can_read_period(p_period_id uuid)
returns boolean language sql stable security definer set search_path=public as $$
  select exists(select 1 from public.playlist_periods p where p.id=p_period_id
    and (not p.is_test or public.is_current_user_tester() or public.is_current_user_admin()));
$$;
revoke all on function public.can_read_period(uuid) from public;
grant execute on function public.can_read_period(uuid) to anon, authenticated;

-- Restrictive policies also constrain any pre-existing permissive SELECT policies.
drop policy if exists songs_test_access on public.songs;
create policy songs_test_access on public.songs as restrictive for select to anon, authenticated
  using (public.can_read_period(period_id));
drop policy if exists periods_test_access on public.playlist_periods;
create policy periods_test_access on public.playlist_periods as restrictive for select to anon, authenticated
  using (not is_test or status='active' or public.is_current_user_tester() or public.is_current_user_admin());

create or replace function public.assert_test_period_access(p_period text,p_cookie text,p_write boolean)
returns void language plpgsql security definer set search_path=public as $$
declare target uuid; test_period boolean;
begin
  begin target=p_period::uuid; exception when invalid_text_representation then return; end;
  -- Serializes mode changes with participation requests, including cancellation.
  select is_test into test_period from public.playlist_periods where id=target for share;
  if coalesce(test_period,false) then
    -- Let revocation wait for an already-authorized request to finish.
    perform 1 from public.test_accounts where user_id=auth.uid() and enabled for share;
    if public.is_current_user_tester() is not true then
      if p_write or public.is_current_user_admin() is not true then
        raise exception '当前为测试期，请使用已授权的测试账号登录。';
      end if;
    end if;
    if p_cookie is distinct from auth.uid()::text then
      raise exception '测试身份已变化，请重新登录。';
    end if;
  end if;
end;
$$;
revoke all on function public.assert_test_period_access(text,text,boolean) from public,anon,authenticated;

-- Every public submission/vote RPC calls this internal entry point before writing.
-- Test identities use the authenticated account UUID rather than a replaceable cookie.
create or replace function public.consume_api_attempt(p_type text,p_period text,p_cookie text)
returns void language plpgsql security definer set search_path=public as $rate$
declare cfg public.security_settings%rowtype; cookie_key text=md5(coalesce(left(btrim(p_cookie),128),'')); ip text; lock_key bigint; cookie_limit int; ip_limit int;
begin
  perform public.assert_test_period_access(p_period,p_cookie,true);
  select * into strict cfg from public.security_settings where id=true;
  ip=public.request_client_ip();
  -- Period mode lock -> sorted rate locks -> actor -> song -> report.
  for lock_key in select distinct key from unnest(array[
    hashtextextended('rate-cookie:'||p_type||':'||cookie_key,0),
    case when ip is null then null else hashtextextended('rate-ip:'||p_type||':'||ip,0) end
  ]) key where key is not null order by key loop perform pg_advisory_xact_lock(lock_key); end loop;
  if p_type='vote' then cookie_limit=cfg.vote_cookie_per_minute; ip_limit=cfg.vote_ip_per_minute;
  elsif p_type='submission' then cookie_limit=cfg.submission_cookie_per_minute; ip_limit=cfg.submission_ip_per_minute;
  else raise exception 'Invalid request type.'; end if;
  if (select count(*) from public.api_request_attempts where attempt_type=p_type and cookie_hash=cookie_key and created_at>=clock_timestamp()-interval '1 minute')>=cookie_limit
    or (ip is not null and (select count(*) from public.api_request_attempts where attempt_type=p_type and client_ip=ip and created_at>=clock_timestamp()-interval '1 minute')>=ip_limit) then
    raise exception '请求过于频繁，请稍后再试。' using errcode='P0001';
  end if;
  insert into public.api_request_attempts(attempt_type,cookie_hash,client_ip,requested_period) values(p_type,cookie_key,ip,left(p_period,64));
end;
$rate$;
revoke all on function public.consume_api_attempt(text,text,text) from public,anon,authenticated;

create or replace function public.get_my_likes(p_playlist_date text,p_voter_cookie text)
returns table(song_id uuid) language plpgsql security definer set search_path=public as $$
declare normalized_cookie text;
begin
  perform public.assert_test_period_access(p_playlist_date,p_voter_cookie,false);
  normalized_cookie=public.assert_valid_voter_cookie(p_voter_cookie);
  return query select l.song_id from public.song_likes l where l.playlist_date=p_playlist_date and l.voter_cookie=normalized_cookie order by l.created_at desc limit 500;
end;
$$;
create or replace function public.get_my_dislikes(p_playlist_date text,p_voter_cookie text)
returns table(song_id uuid) language plpgsql security definer set search_path=public as $$
declare normalized_cookie text;
begin
  perform public.assert_test_period_access(p_playlist_date,p_voter_cookie,false);
  normalized_cookie=public.assert_valid_voter_cookie(p_voter_cookie);
  return query select d.song_id from public.song_dislikes d where d.playlist_date=p_playlist_date and d.voter_cookie=normalized_cookie order by d.created_at desc limit 500;
end;
$$;
revoke all on function public.get_my_likes(text,text),public.get_my_dislikes(text,text) from public;
grant execute on function public.get_my_likes(text,text),public.get_my_dislikes(text,text) to anon,authenticated;

create or replace function public.admin_list_test_accounts()
returns table(user_id uuid,email text,enabled boolean,updated_at timestamptz)
language plpgsql security definer set search_path=public as $$
begin
  if public.is_current_user_admin() is not true then raise exception 'Admin permission required.'; end if;
  return query select t.user_id,u.email::text,t.enabled,t.updated_at from public.test_accounts t join auth.users u on u.id=t.user_id order by t.updated_at desc,t.user_id;
end;
$$;

create or replace function public.admin_set_test_account(p_email text,p_enabled boolean)
returns void language plpgsql security definer set search_path=public as $$
declare target uuid;
begin
  if public.is_current_user_admin() is not true then raise exception 'Admin permission required.'; end if;
  if p_enabled is null or nullif(trim(p_email),'') is null then raise exception '请填写测试账号邮箱。'; end if;
  select id into target from auth.users where lower(email)=lower(trim(p_email));
  if target is null then raise exception '该账号尚未创建，请先在 Supabase Authentication 中创建邮箱账号并设置密码。'; end if;
  insert into public.test_accounts(user_id,enabled,granted_by,updated_at) values(target,p_enabled,auth.uid(),clock_timestamp())
    on conflict(user_id) do update set enabled=excluded.enabled,granted_by=excluded.granted_by,updated_at=excluded.updated_at;
  insert into public.admin_action_log(actor_id,actor_name,action,target_id,details)
    values(auth.uid(),coalesce(auth.jwt()->>'email',auth.uid()::text),case when p_enabled then 'grant_test_account' else 'revoke_test_account' end,target,jsonb_build_object('email',lower(trim(p_email))));
end;
$$;

create or replace function public.admin_set_period_test_mode(p_period_id uuid,p_enabled boolean,p_expected boolean)
returns void language plpgsql security definer set search_path=public as $$
declare previous public.playlist_periods%rowtype;
begin
  if public.is_current_user_admin() is not true then raise exception 'Admin permission required.'; end if;
  if p_enabled is null or p_expected is null then raise exception '测试模式参数无效。'; end if;
  select * into previous from public.playlist_periods where id=p_period_id for update;
  if not found or previous.status<>'active' then raise exception '当前征集期已变化，请刷新后重试。'; end if;
  if previous.is_test is distinct from p_expected then raise exception '测试模式已被其他运营人员修改，请刷新后重试。'; end if;
  if p_enabled and not exists(select 1 from public.test_accounts where enabled) then raise exception '请先授权至少一个测试账号。'; end if;
  update public.playlist_periods set is_test=p_enabled,updated_at=clock_timestamp() where id=p_period_id;
  insert into public.admin_action_log(actor_id,actor_name,action,target_id,details)
    values(auth.uid(),coalesce(auth.jwt()->>'email',auth.uid()::text),'set_test_mode',p_period_id,jsonb_build_object('before',previous.is_test,'after',p_enabled));
end;
$$;
revoke all on function public.admin_list_test_accounts(),public.admin_set_test_account(text,boolean),public.admin_set_period_test_mode(uuid,boolean,boolean) from public,anon,authenticated;
grant execute on function public.admin_list_test_accounts(),public.admin_set_test_account(text,boolean),public.admin_set_period_test_mode(uuid,boolean,boolean) to authenticated;

notify pgrst, 'reload schema';

-- ===== supabase-qq-participation.sql =====
-- Incremental migration: run AFTER supabase-test-mode.sql. Keeps existing data.
-- Public browsing stays available; all participation goes through the QQ backend.

do $prerequisites$
begin
  if to_regprocedure('public.assert_test_period_access(text,text,boolean)') is null
    or to_regclass('public.test_accounts') is null then
    raise exception '请先执行 supabase-test-mode.sql；本迁移不会清空数据。';
  end if;
end;
$prerequisites$;

create table if not exists public.qq_accounts (
  id uuid primary key default gen_random_uuid(),
  app_id text not null check (app_id ~ '^[0-9]+$'),
  openid text not null check (length(openid) between 1 and 128),
  nickname text not null,
  avatar text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (app_id,openid)
);
alter table public.qq_accounts enable row level security;
revoke all on public.qq_accounts from public,anon,authenticated;
grant select on public.qq_accounts to authenticated;
drop policy if exists qq_accounts_admin_read on public.qq_accounts;
create policy qq_accounts_admin_read on public.qq_accounts for select to authenticated
  using (public.is_current_user_admin());

-- The backend supplies the profile from its verified HttpOnly QQ session. Only a
-- server Secret/service_role key may call this entry point, never the browser.
create or replace function public.qq_participate(
  p_app_id text,p_openid text,p_nickname text,p_avatar text,
  p_operation text,p_period_id uuid,p_song_id uuid default null,
  p_title text default null,p_artist text default null,p_action text default null,
  p_reason text default null,p_test_user_id uuid default null,p_client_ip text default null
)
returns jsonb language plpgsql security definer set search_path=public as $qq$
declare account_id uuid; actor text; test_period boolean; result jsonb;
  previous_sub text=current_setting('request.jwt.claim.sub',true);
  previous_claims text=current_setting('request.jwt.claims',true);
  previous_headers text=current_setting('request.headers',true);
begin
  if p_operation is null or p_operation not in ('votes','submit','like','dislike')
    or p_app_id is null or p_app_id !~ '^[0-9]+$'
    or nullif(trim(p_openid),'') is null or length(p_openid)>128 then
    return jsonb_build_object('error','invalid_request');
  end if;
  -- Same lock order as test-mode changes and the existing rate-limit guard.
  select is_test into test_period from public.playlist_periods where id=p_period_id for share;
  if not found then return jsonb_build_object('error','period_unavailable'); end if;
  if test_period then
    perform 1 from public.test_accounts where user_id=p_test_user_id and enabled for share;
    if not found then return jsonb_build_object('error','test_login_required'); end if;
  end if;
  insert into public.qq_accounts(app_id,openid,nickname,avatar)
    values(p_app_id,p_openid,left(coalesce(p_nickname,'QQ 用户'),100),left(coalesce(p_avatar,''),2048))
    on conflict(app_id,openid) do update set nickname=excluded.nickname,avatar=excluded.avatar,updated_at=clock_timestamp()
    returning id into account_id;
  -- Formal periods use the persistent QQ account UUID. Test periods keep their
  -- existing tester UUID and additionally require QQ login at the backend.
  actor=case when test_period then p_test_user_id::text else account_id::text end;
  perform set_config('request.jwt.claim.sub',coalesce(p_test_user_id::text,''),true);
  perform set_config('request.jwt.claims',jsonb_build_object('role','service_role','sub',p_test_user_id)::text,true);
  -- The backend supplies the peer IP from Nginx, not a browser field. Otherwise
  -- every visitor would share the backend server's Supabase rate-limit IP.
  if p_client_ip is not null then perform p_client_ip::inet; end if;
  perform set_config('request.headers',jsonb_build_object('x-real-ip',p_client_ip)::text,true);
  if p_operation='votes' then
    result=jsonb_build_object(
      'likes',(select coalesce(jsonb_agg(song_id),'[]'::jsonb) from public.get_my_likes(p_period_id::text,actor)),
      'dislikes',(select coalesce(jsonb_agg(song_id),'[]'::jsonb) from public.get_my_dislikes(p_period_id::text,actor)));
  elsif p_operation='submit' then
    select to_jsonb(r) into result from public.submit_song(p_title,p_artist,p_period_id::text,actor) r;
  elsif p_operation='like' and p_action in ('on','off') then
    select to_jsonb(r) into result from public.toggle_song_like(p_song_id,p_period_id::text,actor,
      case p_action when 'on' then 'like' else 'unlike' end) r;
  elsif p_operation='dislike' and p_action in ('on','off') then
    select to_jsonb(r) into result from public.toggle_song_dislike(p_song_id,p_period_id::text,actor,
      case p_action when 'on' then 'dislike' else 'undislike' end,p_reason) r;
  else
    result=jsonb_build_object('error','invalid_request');
  end if;
  perform set_config('request.jwt.claim.sub',coalesce(previous_sub,''),true);
  perform set_config('request.jwt.claims',coalesce(previous_claims,''),true);
  perform set_config('request.headers',coalesce(previous_headers,''),true);
  -- Only business errors from our existing RPCs are returned. SQL/permission
  -- failures remain generic at the HTTP boundary. Counters remain committed.
  if result->>'error_message' like '本浏览器%' then
    result=jsonb_set(result,'{error_message}',to_jsonb(replace(result->>'error_message','本浏览器','本账号')));
  end if;
  return result;
exception when sqlstate 'P0001' then
  -- Rate-limit failures occur before a new attempt is inserted. Return a stable
  -- code instead of leaking arbitrary SQL error text through the HTTP gateway.
  return jsonb_build_object('error',case when sqlerrm='请求过于频繁，请稍后再试。'
    then 'rate_limited' else 'period_unavailable' end);
end;
$qq$;
revoke all on function public.qq_participate(text,text,text,text,text,uuid,uuid,text,text,text,text,uuid,text) from public,anon,authenticated;
grant execute on function public.qq_participate(text,text,text,text,text,uuid,uuid,text,text,text,text,uuid,text) to service_role;

-- Close the old anonymous paths, including reads of another actor's vote state.
-- Internal SECURITY DEFINER calls above keep using the tested business logic.
revoke all on function public.submit_song(text,text,text,text),
  public.toggle_song_like(uuid,text,text,text),
  public.toggle_song_dislike(uuid,text,text,text,text),
  public.get_my_likes(text,text),public.get_my_dislikes(text,text)
  from public,anon,authenticated;

notify pgrst, 'reload schema';

-- ===== supabase-account-moderation.sql =====
-- Incremental migration AFTER supabase-qq-participation.sql. Preserves all data.
-- Always apply this last: it installs the guarded QQ participation gateway.

do $prerequisites$ begin
  if to_regclass('public.qq_accounts') is null or to_regclass('public.admin_action_log') is null then
    raise exception '请先执行 QQ 登录和管理工作流迁移；本迁移不会清空数据。';
  end if;
end; $prerequisites$;

create table if not exists public.account_moderation (
  account_id uuid primary key references public.qq_accounts(id),
  vote_until timestamptz,
  submission_until timestamptz,
  ban_until timestamptz,
  version bigint not null default 0 check(version>=0)
);
create table if not exists public.account_moderation_actions (
  id uuid primary key default gen_random_uuid(),
  account_id uuid not null references public.qq_accounts(id),
  action text not null check(action in ('warn','restrict_vote','restrict_submission','ban','lift_vote','lift_submission','unban')),
  reason text not null check(length(trim(reason)) between 1 and 500),
  expires_at timestamptz,
  actor_id uuid not null,
  actor_name text not null,
  created_at timestamptz not null default clock_timestamp(),
  unique(id,account_id)
);
create index if not exists account_moderation_actions_account_idx on public.account_moderation_actions(account_id,created_at desc,id);
create table if not exists public.account_notice_reads (
  account_id uuid not null references public.qq_accounts(id),
  action_id uuid not null,
  read_at timestamptz not null default clock_timestamp(),
  primary key(account_id,action_id),
  foreign key(action_id,account_id) references public.account_moderation_actions(id,account_id)
);
alter table public.account_moderation enable row level security;
alter table public.account_moderation_actions enable row level security;
alter table public.account_notice_reads enable row level security;
revoke all on public.account_moderation,public.account_moderation_actions,public.account_notice_reads from public,anon,authenticated;
-- No client has direct table writes, including an authenticated administrator.
grant select on public.account_moderation,public.account_moderation_actions to authenticated;
drop policy if exists account_moderation_admin_read on public.account_moderation;
create policy account_moderation_admin_read on public.account_moderation for select to authenticated using(public.is_current_user_admin());
drop policy if exists account_actions_admin_read on public.account_moderation_actions;
create policy account_actions_admin_read on public.account_moderation_actions for select to authenticated using(public.is_current_user_admin());

create or replace function public.qq_moderation_state(p_account_id uuid)
returns jsonb language sql volatile security definer set search_path=public as $$
  select jsonb_build_object('version',coalesce(m.version,0),
    'banned',coalesce(m.ban_until>clock_timestamp(),false),
    'vote_restricted',coalesce(m.vote_until>clock_timestamp(),false),
    'submission_restricted',coalesce(m.submission_until>clock_timestamp(),false),
    'ban_until',case when m.ban_until='infinity'::timestamptz then null else m.ban_until end,
    'vote_until',case when m.vote_until='infinity'::timestamptz then null else m.vote_until end,
    'submission_until',case when m.submission_until='infinity'::timestamptz then null else m.submission_until end)
  from (select p_account_id id) a left join public.account_moderation m on m.account_id=a.id;
$$;
revoke all on function public.qq_moderation_state(uuid) from public,anon,authenticated,service_role;

create or replace function public.assert_qq_account_allowed(p_account_id uuid,p_operation text)
returns void language plpgsql security definer set search_path=public as $$
declare m public.account_moderation%rowtype;
begin
  if p_operation='votes' then return; end if; -- Personal state remains readable.
  select * into m from public.account_moderation where account_id=p_account_id;
  if m.ban_until>clock_timestamp() then raise exception 'account_banned' using errcode='P0002'; end if;
  if p_operation in ('like','dislike') and m.vote_until>clock_timestamp() then raise exception 'voting_restricted' using errcode='P0002'; end if;
  if p_operation='submit' and m.submission_until>clock_timestamp() then raise exception 'submission_restricted' using errcode='P0002'; end if;
end;
$$;
revoke all on function public.assert_qq_account_allowed(uuid,text) from public,anon,authenticated,service_role;

create or replace function public.admin_list_qq_accounts(p_search text default '',p_offset integer default 0,p_limit integer default 20)
returns jsonb language plpgsql security definer set search_path=public as $$
declare result jsonb; keyword text=left(trim(coalesce(p_search,'')),100);
begin
  if public.is_current_user_admin() is not true then raise exception 'Admin permission required.'; end if;
  if p_offset is null or p_offset<0 or p_limit is null or p_limit not between 1 and 100 then raise exception '分页参数无效。'; end if;
  select jsonb_build_object('total',(select count(*) from public.qq_accounts a where keyword='' or a.id::text=keyword or a.nickname ilike '%'||keyword||'%'),
    'items',coalesce(jsonb_agg(to_jsonb(rows)),'[]'::jsonb)) into result from (
    select a.id,a.nickname,a.avatar,a.created_at,a.updated_at,public.qq_moderation_state(a.id) moderation
    from public.qq_accounts a where keyword='' or a.id::text=keyword or a.nickname ilike '%'||keyword||'%'
    order by a.updated_at desc,a.id limit p_limit offset p_offset
  ) rows;
  return result;
end;
$$;

create or replace function public.admin_get_account_moderation(p_account_id uuid)
returns jsonb language plpgsql security definer set search_path=public as $$
declare account public.qq_accounts%rowtype;
begin
  if public.is_current_user_admin() is not true then raise exception 'Admin permission required.'; end if;
  select * into account from public.qq_accounts where id=p_account_id;
  if not found then raise exception '站内账号不存在，请刷新账号列表。'; end if;
  return jsonb_build_object('account',jsonb_build_object('id',account.id,'nickname',account.nickname,'avatar',account.avatar),
    'moderation',public.qq_moderation_state(account.id),
    'actions',(select coalesce(jsonb_agg(to_jsonb(events)),'[]'::jsonb) from (
      select id,action,reason,expires_at,actor_name,created_at from public.account_moderation_actions
      where account_id=account.id order by created_at desc,id limit 100
    ) events));
end;
$$;

create or replace function public.admin_moderate_account(p_account_id uuid,p_action text,p_reason text,p_duration_hours integer,p_expected_version bigint)
returns void language plpgsql security definer set search_path=public as $$
declare current_version bigint; expiry timestamptz; name text; event_id uuid;
begin
  if public.is_current_user_admin() is not true then raise exception 'Admin permission required.'; end if;
  if nullif(trim(p_reason),'') is null or length(trim(p_reason))>500 then raise exception '请填写 1–500 字的处理原因。'; end if;
  if p_action is null or p_action not in ('warn','restrict_vote','restrict_submission','ban','lift_vote','lift_submission','unban') then raise exception '处理类型无效。'; end if;
  if p_expected_version is null or p_expected_version<0 then raise exception '请先刷新账号状态。'; end if;
  if p_action in ('restrict_vote','restrict_submission','ban') then
    if p_duration_hours is not null and p_duration_hours not between 1 and 87600 then raise exception '限制时长须为 1–87600 小时，或选择长期。'; end if;
    expiry=case when p_duration_hours is null then 'infinity'::timestamptz else clock_timestamp()+make_interval(hours=>p_duration_hours) end;
  elsif p_duration_hours is not null then raise exception '警告和解除限制不需要设置时长。'; end if;
  -- Gateway writes already lock this account after their period lock. Waiting
  -- here makes a committed restriction apply to every following write request.
  perform 1 from public.qq_accounts where id=p_account_id for update;
  if not found then raise exception '站内账号不存在。'; end if;
  insert into public.account_moderation(account_id) values(p_account_id) on conflict do nothing;
  select version into current_version from public.account_moderation where account_id=p_account_id for update;
  if current_version<>p_expected_version then raise exception '账号状态已被其他管理员修改，请重新读取后再处理。'; end if;
  update public.account_moderation set
    vote_until=case p_action when 'restrict_vote' then expiry when 'lift_vote' then null else vote_until end,
    submission_until=case p_action when 'restrict_submission' then expiry when 'lift_submission' then null else submission_until end,
    ban_until=case p_action when 'ban' then expiry when 'unban' then null else ban_until end,
    version=version+1 where account_id=p_account_id;
  name=coalesce(auth.jwt()->>'email',auth.uid()::text);
  insert into public.account_moderation_actions(account_id,action,reason,expires_at,actor_id,actor_name)
    values(p_account_id,p_action,trim(p_reason),case when expiry='infinity'::timestamptz then null else expiry end,auth.uid(),name)
    returning id into event_id;
  insert into public.admin_action_log(actor_id,actor_name,action,target_id,details)
    values(auth.uid(),name,'account_'||p_action,p_account_id,jsonb_build_object('reason',trim(p_reason),'notice_id',event_id,'expires_at',case when expiry='infinity'::timestamptz then null else expiry end));
end;
$$;
revoke all on function public.admin_list_qq_accounts(text,integer,integer),public.admin_get_account_moderation(uuid),
  public.admin_moderate_account(uuid,text,text,integer,bigint) from public,anon,authenticated,service_role;
grant execute on function public.admin_list_qq_accounts(text,integer,integer),public.admin_get_account_moderation(uuid),
  public.admin_moderate_account(uuid,text,text,integer,bigint) to authenticated;

create or replace function public.qq_account_status(p_app_id text,p_openid text,p_nickname text,p_avatar text)
returns jsonb language plpgsql security definer set search_path=public as $$
declare target_account_id uuid;
begin
  if p_app_id is null or p_app_id !~ '^[0-9]+$' or nullif(trim(p_openid),'') is null or length(p_openid)>128 then raise exception 'Invalid identity.'; end if;
  insert into public.qq_accounts(app_id,openid,nickname,avatar)
    values(p_app_id,p_openid,left(coalesce(p_nickname,'QQ 用户'),100),left(coalesce(p_avatar,''),2048))
    on conflict(app_id,openid) do update set nickname=excluded.nickname,avatar=excluded.avatar,updated_at=clock_timestamp() returning id into target_account_id;
  return jsonb_build_object('id',target_account_id,'moderation',public.qq_moderation_state(target_account_id),
    'unread_count',(select count(*) from public.account_moderation_actions a where a.account_id=target_account_id
      and not exists(select 1 from public.account_notice_reads r where r.account_id=a.account_id and r.action_id=a.id)),
    'notices',(select coalesce(jsonb_agg(to_jsonb(events)),'[]'::jsonb) from (
      select a.id,a.action,a.reason,a.expires_at,a.created_at,exists(select 1 from public.account_notice_reads r where r.account_id=a.account_id and r.action_id=a.id) is_read
      from public.account_moderation_actions a where a.account_id=target_account_id order by a.created_at desc,a.id limit 50
    ) events));
end;
$$;

create or replace function public.qq_read_account_notice(p_app_id text,p_openid text,p_notice_id uuid default null)
returns jsonb language plpgsql security definer set search_path=public as $$
declare target uuid;
begin
  select id into target from public.qq_accounts where app_id=p_app_id and openid=p_openid;
  if target is null then return jsonb_build_object('error','notice_not_found'); end if;
  if p_notice_id is not null and not exists(select 1 from public.account_moderation_actions where id=p_notice_id and account_id=target) then
    return jsonb_build_object('error','notice_not_found');
  end if;
  insert into public.account_notice_reads(account_id,action_id)
    select target,id from public.account_moderation_actions where account_id=target and (p_notice_id is null or id=p_notice_id)
    on conflict do nothing;
  return jsonb_build_object('ok',true);
end;
$$;
revoke all on function public.qq_account_status(text,text,text,text),public.qq_read_account_notice(text,text,uuid) from public,anon,authenticated,service_role;
grant execute on function public.qq_account_status(text,text,text,text),public.qq_read_account_notice(text,text,uuid) to service_role;

-- GUARDED_GATEWAY: based on supabase-qq-participation.sql, plus account checks.

create or replace function public.qq_participate(
  p_app_id text,p_openid text,p_nickname text,p_avatar text,
  p_operation text,p_period_id uuid,p_song_id uuid default null,
  p_title text default null,p_artist text default null,p_action text default null,
  p_reason text default null,p_test_user_id uuid default null,p_client_ip text default null
)
returns jsonb language plpgsql security definer set search_path=public as $qq$
declare account_id uuid; actor text; test_period boolean; result jsonb;
  previous_sub text=current_setting('request.jwt.claim.sub',true);
  previous_claims text=current_setting('request.jwt.claims',true);
  previous_headers text=current_setting('request.headers',true);
begin
  if p_operation is null or p_operation not in ('votes','submit','like','dislike')
    or p_app_id is null or p_app_id !~ '^[0-9]+$'
    or nullif(trim(p_openid),'') is null or length(p_openid)>128 then
    return jsonb_build_object('error','invalid_request');
  end if;
  -- Same lock order as test-mode changes and the existing rate-limit guard.
  select is_test into test_period from public.playlist_periods where id=p_period_id for share;
  if not found then return jsonb_build_object('error','period_unavailable'); end if;
  if test_period then
    perform 1 from public.test_accounts where user_id=p_test_user_id and enabled for share;
    if not found then return jsonb_build_object('error','test_login_required'); end if;
  end if;
  insert into public.qq_accounts(app_id,openid,nickname,avatar)
    values(p_app_id,p_openid,left(coalesce(p_nickname,'QQ 用户'),100),left(coalesce(p_avatar,''),2048))
    on conflict(app_id,openid) do update set nickname=excluded.nickname,avatar=excluded.avatar,updated_at=clock_timestamp()
    returning id into account_id;
  perform public.assert_qq_account_allowed(account_id,p_operation);
  -- Formal periods use the persistent QQ account UUID. Test periods keep their
  -- existing tester UUID and additionally require QQ login at the backend.
  actor=case when test_period then p_test_user_id::text else account_id::text end;
  perform set_config('request.jwt.claim.sub',coalesce(p_test_user_id::text,''),true);
  perform set_config('request.jwt.claims',jsonb_build_object('role','service_role','sub',p_test_user_id)::text,true);
  -- The backend supplies the peer IP from Nginx, not a browser field. Otherwise
  -- every visitor would share the backend server's Supabase rate-limit IP.
  if p_client_ip is not null then perform p_client_ip::inet; end if;
  perform set_config('request.headers',jsonb_build_object('x-real-ip',p_client_ip)::text,true);
  if p_operation='votes' then
    result=jsonb_build_object(
      'likes',(select coalesce(jsonb_agg(song_id),'[]'::jsonb) from public.get_my_likes(p_period_id::text,actor)),
      'dislikes',(select coalesce(jsonb_agg(song_id),'[]'::jsonb) from public.get_my_dislikes(p_period_id::text,actor)));
  elsif p_operation='submit' then
    select to_jsonb(r) into result from public.submit_song(p_title,p_artist,p_period_id::text,actor) r;
  elsif p_operation='like' and p_action in ('on','off') then
    select to_jsonb(r) into result from public.toggle_song_like(p_song_id,p_period_id::text,actor,
      case p_action when 'on' then 'like' else 'unlike' end) r;
  elsif p_operation='dislike' and p_action in ('on','off') then
    select to_jsonb(r) into result from public.toggle_song_dislike(p_song_id,p_period_id::text,actor,
      case p_action when 'on' then 'dislike' else 'undislike' end,p_reason) r;
  else
    result=jsonb_build_object('error','invalid_request');
  end if;
  perform set_config('request.jwt.claim.sub',coalesce(previous_sub,''),true);
  perform set_config('request.jwt.claims',coalesce(previous_claims,''),true);
  perform set_config('request.headers',coalesce(previous_headers,''),true);
  -- Only business errors from our existing RPCs are returned. SQL/permission
  -- failures remain generic at the HTTP boundary. Counters remain committed.
  if result->>'error_message' like '本浏览器%' then
    result=jsonb_set(result,'{error_message}',to_jsonb(replace(result->>'error_message','本浏览器','本账号')));
  end if;
  return result;
exception when sqlstate 'P0002' then
  return jsonb_build_object('error',case when sqlerrm in ('account_banned','voting_restricted','submission_restricted') then sqlerrm else 'participation_unavailable' end);
when sqlstate 'P0001' then
  -- Rate-limit failures occur before a new attempt is inserted. Return a stable
  -- code instead of leaking arbitrary SQL error text through the HTTP gateway.
  return jsonb_build_object('error',case when sqlerrm='请求过于频繁，请稍后再试。'
    then 'rate_limited' else 'period_unavailable' end);
end;
$qq$;
revoke all on function public.qq_participate(text,text,text,text,text,uuid,uuid,text,text,text,text,uuid,text) from public,anon,authenticated;
grant execute on function public.qq_participate(text,text,text,text,text,uuid,uuid,text,text,text,text,uuid,text) to service_role;


-- END_GUARDED_GATEWAY

create or replace function public.qq_moderation_health()
returns jsonb language sql stable security definer set search_path=public as $$
  select jsonb_build_object('ok',position('assert_qq_account_allowed' in pg_get_functiondef(
    'public.qq_participate(text,text,text,text,text,uuid,uuid,text,text,text,text,uuid,text)'::regprocedure))>0,'version',1);
$$;
revoke all on function public.qq_moderation_health() from public,anon,authenticated,service_role;
grant execute on function public.qq_moderation_health() to service_role;

